// Emulation of CPython's float() string parsing and repr() formatting,
// which the original script relies on implicitly (argparse type=float and
// moneyed's Decimal(str(amount)) conversion).

const PY_WS = ' \t\n\r\v\f';

function stripPyWhitespace(s) {
  let start = 0;
  let end = s.length;
  while (start < end && PY_WS.includes(s[start])) start++;
  while (end > start && PY_WS.includes(s[end - 1])) end--;
  return s.slice(start, end);
}

// Python numeric grammar: digitpart = digit (["_"] digit)*
const DIGIT_PART = '\\d(?:_?\\d)*';
const FLOAT_RE = new RegExp(
  '^[+-]?(?:' +
    DIGIT_PART + '\\.?(?:' + DIGIT_PART + ')?' + // "1", "1.", "1.5"
    '|\\.' + DIGIT_PART + // ".5"
  ')(?:[eE][+-]?' + DIGIT_PART + ')?$'
);
const INF_NAN_RE = /^[+-]?(?:inf(?:inity)?|nan)$/i;

export class PyFloatError extends Error {}

// Parse a string exactly like CPython's float(). Throws PyFloatError on
// invalid input. Returns a JS number.
export function pyFloat(s) {
  const t = stripPyWhitespace(s);
  if (INF_NAN_RE.test(t)) {
    const negative = t[0] === '-';
    const body = t.replace(/^[+-]/, '').toLowerCase();
    if (body.startsWith('inf')) return negative ? -Infinity : Infinity;
    return NaN;
  }
  if (!FLOAT_RE.test(t)) throw new PyFloatError(`could not convert string to float: ${s}`);
  return Number(t.replace(/_/g, ''));
