// Python uses the shortest round-trip digits (same as JS Number#toExponential
// without arguments) and then formats fixed for -4 < decpt <= 16, else
// exponential with a signed, at-least-two-digit exponent.
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  const negative = x < 0 || Object.is(x, -0);
  const sign = negative ? '-' : '';
