  if (decpt > 16 || decpt < -3) {
    const mant = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const e = decpt - 1;
    const expText = (e < 0 ? '-' : '+') + String(Math.abs(e)).padStart(2, '0');
