// money.mjs
// Re-implementation of the moneyed.Money behaviour used by the original
// script: construction from a float amount (converted via Decimal(str(amount)))
// and division by a number.

import { PyDecimal, decimalFromString, decimalHalve } from './pydecimal.mjs';
import { pyFloatRepr } from './pyfloat.mjs';
import { getCurrency, CurrencyDoesNotExist } from './currencies.mjs';

export { CurrencyDoesNotExist };

export class Money {
  // amount: JS number (a Python float) or an already-computed PyDecimal.
  constructor(amount, currency) {
    this.currency = getCurrency(currency);
    if (amount instanceof PyDecimal) {
      this.amount = amount;
    } else {
      // moneyed: Decimal(str(amount)) for non-Decimal input
      this.amount = decimalFromString(pyFloatRepr(amount));
    }
  }

  // moneyed's Money.__truediv__: returns Money(self.amount / other, currency).
  // The original script only ever divides by 2, which is exact under the
  // default decimal context, so only that divisor is supported.
  div(other) {
    if (other === 2) {
      return new Money(decimalHalve(this.amount), this.currency);
    }
    throw new Error(`unsupported divisor: ${other}`);
  }
}

// argparse.mjs
// Minimal re-implementation of the Python argparse behaviour of the original
// script: two required options (--amount float, --currency str) plus -h/--help.
// Supports "--opt value", "--opt=value", unambiguous prefix abbreviations,
// negative-number values, and reproduces argparse's error/exit-code contract.

import { pyFloat, PyFloatError } from './pyfloat.mjs';
import { pyRepr } from './pystr.mjs';

// argparse's _negative_number_matcher; tokens matching this are treated as
// values rather than options (the parser has no options that look like
// negative numbers).
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

const LONG_OPTIONS = ['--help', '--amount', '--currency'];

export function parseArgs(argv, prog) {
  const usage = `usage: ${prog} [-h] --amount AMOUNT --currency CURRENCY`;

  const fail = (message) => {
    process.stderr.write(usage + '\n');
    process.stderr.write(`${prog}: error: ${message}\n`);
    process.exit(2);
  };

  const printHelp = () => {
    process.stdout.write(
      usage + '\n' +
      '\n' +
      'options:\n' +
      '  -h, --help           show this help message and exit\n' +
      '  --amount AMOUNT\n' +
      '  --currency CURRENCY\n'
    );
    process.exit(0);
  };

  const result = { amount: undefined, currency: undefined };
  const extras = [];
  let afterDoubleDash = false;
  let i = 0;

  const takeValue = (actionName, inlineValue) => {
    if (inlineValue !== null) return inlineValue;
    const next = argv[i + 1];
    const looksLikeOption =
      next !== undefined && next.length > 1 && next[0] === '-' && !NEGATIVE_NUMBER_RE.test(next);
    if (next === undefined || looksLikeOption) {
      fail(`argument ${actionName}: expected one argument`);
    }
    i++;
    return next;
  };

  while (i < argv.length) {
    const tok = argv[i];

    if (afterDoubleDash) {
      extras.push(tok);
    } else if (tok === '--') {
      afterDoubleDash = true;
    } else if (tok.startsWith('--')) {
      let name = tok;
      let inlineValue = null;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        inlineValue = tok.slice(eq + 1);
      }

      let match = LONG_OPTIONS.includes(name) ? name : null;
      if (match === null) {
        const candidates = LONG_OPTIONS.filter((o) => o.startsWith(name));
        if (candidates.length === 1) match = candidates[0];
        else if (candidates.length > 1) {
          fail(`ambiguous option: ${name} could match ${candidates.join(', ')}`);
        }
      }

      if (match === null) {
        extras.push(tok);
      } else if (match === '--help') {
        printHelp();
      } else {
        const value = takeValue(match, inlineValue);
        if (match === '--amount') {
          try {
            result.amount = pyFloat(value);
          } catch (err) {
            if (!(err instanceof PyFloatError)) throw err;
            fail(`argument --amount: invalid float value: ${pyRepr(value)}`);
          }
        } else {
          result.currency = value;
        }
      }
    } else if (tok === '-h') {
      printHelp();
    } else {
      // unknown short option, negative-number-like token, or bare value
      extras.push(tok);
    }
    i++;
  }

  const missing = [];
  if (result.amount === undefined) missing.push('--amount');
  if (result.currency === undefined) missing.push('--currency');
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return result;
}

